package io.xeros.solo;
import io.xeros.*;import io.xeros.content.bosses.*;import io.xeros.content.bosses.kratos.*;import io.xeros.content.bosses.wildypursuit.*;import io.xeros.content.combat.*;import io.xeros.content.combat.core.*;import io.xeros.content.instances.*;import io.xeros.model.*;import io.xeros.model.entity.npc.*;import io.xeros.model.entity.player.*;import io.xeros.model.entity.player.save.PlayerSave;import io.xeros.model.items.*;import java.util.*;
public class BossesExtra69Check {
 static void ok(boolean b,String s){if(!b)throw new AssertionError(s);}static Player actor(){Player p=WeaponsEquipment69Check.actor();p.getHealth().setMaximumHealth(5000);p.getHealth().reset();return p;}static void at(Player p,NPC n){BossRoutesCheck.at(p,n.getX()+1,n.getY(),n.getHeight());n.spawnedBy=p.getIndex();n.killedBy=p.getIndex();n.oldIndex=p.getIndex();n.setPlayerAttackingIndex(p.getIndex());}static void clear(Player p){ToaSoloPlayableCheck.clear(p);}static void tick(int n){SkillsAuditCheck.tick(n);}static void process(NPC n,int ticks){for(int i=0;i<ticks&&!n.isUnregister();i++)Server.npcHandler.getNpcProcess().process(n.getIndex());}
 static void scorpia(){Player p=actor();NPC n=NPCHandler.getNpc(6615);at(p,n);n.getHealth().setCurrentHealth(90);Scorpia.spawnHealer(n);List<NPC> healers=new ArrayList<>();for(NPC h:NPCHandler.npcs)if(h!=null&&h.getNpcId()==6617&&!h.isUnregister()){healers.add(h);h.teleport(n.getX(),n.getY(),n.getHeight());}ok(healers.size()==2,"Two guardians");tick(4);ok(n.getHealth().getCurrentHealth()>90,"Guardians heal");int hp=n.getHealth().getCurrentHealth();for(NPC h:healers)h.freezeTimer=50;tick(8);ok(n.getHealth().getCurrentHealth()==hp,"Freeze interrupts guardian healing");tick(28);ok(healers.stream().allMatch(NPC::isUnregister),"Inactive guardian cleanup");n.getHealth().setCurrentHealth(180);clear(p);System.out.println("SCORPIA_TWO_GUARDIANS_HEAL_FREEZE_AND_TIMEOUT_PASS");}
 static void vetion()throws Exception{Player p=actor();NPC n=NPCHandler.getNpc(6611);at(p,n);n.getHealth().setCurrentHealth(n.getHealth().getMaximumHealth()/2-1);process(n,1);List<NPC> dogs=new ArrayList<>();for(NPC h:NPCHandler.npcs)if(h!=null&&h.getNpcId()==Npcs.SKELETON_HELLHOUND&&!h.isUnregister()&&!h.isDead()&&h.getPosition().withinDistance(n.getPosition(),25))dogs.add(h);ok(dogs.size()==2,"Vetion dogs");ok(!AttackNpcCheck.check(p,n,false),"Vetion vulnerable during dog wave");for(NPC h:dogs)h.unregisterInstant();int kc=p.getNpcDeathTracker().getKc(n.getName());n.appendDamage(p,n.getHealth().getCurrentHealth(),Hitmark.HIT);process(n,5);ok(n.getNpcId()==6612&&!n.isDead()&&p.getNpcDeathTracker().getKc(n.getName())==kc,"First form incorrectly grants death/KC");n.getHealth().setCurrentHealth(n.getHealth().getMaximumHealth()/2-1);process(n,1);int count=0;for(NPC h:NPCHandler.npcs)if(h!=null&&h.getNpcId()==Npcs.SKELETON_HELLHOUND&&!h.isUnregister()&&!h.isDead()&&h.getPosition().withinDistance(n.getPosition(),25)){count++;h.unregisterInstant();}ok(count==2,"Second phase dog wave");BossesPending69Check.death(p,n);clear(p);System.out.println("VETION_TWO_FORMS_TWO_DOG_WAVES_INVULNERABILITY_FINAL_DEATH_DROP_KC_SAVE_PASS");}
 static void kratos()throws Exception{Player p=actor();KratosNpc n=new KratosNpc(6009,new Position(3027,5233,0));at(p,n);n.getHealth().setCurrentHealth((int)(n.getHealth().getMaximumHealth()*.6));n.process();int count=0;for(NPC h:NPCHandler.npcs)if(h!=null&&(h.getNpcId()==6005||h.getNpcId()==6006)&&!h.isUnregister())count++;ok(count==3,"Kratos first wave");n.getHealth().setCurrentHealth((int)(n.getHealth().getMaximumHealth()*.3));n.process();count=0;for(NPC h:NPCHandler.npcs)if(h!=null&&(h.getNpcId()==6005||h.getNpcId()==6006)&&!h.isUnregister())count++;ok(count==6,"Kratos second wave");n.appendDamage(p,n.getHealth().getCurrentHealth(),Hitmark.HIT);process(n,5);ok(n.getNpcId()==6008&&!n.isDead(),"Kratos second form");n.appendDamage(p,n.getHealth().getCurrentHealth(),Hitmark.HIT);process(n,45);ok(p.getItems().getInventoryCount(7302)==1,"Kratos reward key");ok(Arrays.stream(NPCHandler.npcs).filter(Objects::nonNull).filter(h->h.getNpcId()==6005||h.getNpcId()==6006).allMatch(NPC::isUnregister),"Kratos cleanup");n.unregisterInstant();clear(p);System.out.println("KRATOS_TWO_WAVES_TRANSFORM_FINAL_KEY_AND_MINION_CLEANUP_PASS");}
 static void hunllef()throws Exception{Player p=actor();p.getItems().addItem(23951,1);Hunllef.start(p);tick(15);BossesPlayableCheck.applied(p);ok(p.getInstance() instanceof Hunllef,"Hunllef access");NPC n=p.getInstance().getNpcs().get(0);n.appendDamage(p,n.getHealth().getCurrentHealth(),Hitmark.HIT);process(n,45);tick(3);ok(p.getItems().getInventoryCount(23776)==1&&p.getInstance()==null,"Hunllef completion key/exit");Hunllef.rewardPlayers(p);ok(p.getItems().getInventoryCount(23776)==1,"Duplicate Hunllef key");clear(p);System.out.println("HUNLLEF_NATIVE_KEY_ENTRY_FINAL_DEATH_PRIZE_EXIT_SINGLE_CLAIM_PASS");}
 static void seren()throws Exception{Player p=actor();NPC n=NPCHandler.getNpc(8920);at(p,n);FragmentOfSeren.specialAmount=0;FragmentOfSeren.isAttackable=true;n.getHealth().setCurrentHealth(500);HitExecutor.getDelayedHit(p,n,new Damage(n,80,1,p.playerEquipment,Hitmark.HIT,CombatType.MELEE)).hit();ok(FragmentOfSeren.activePillars.size()==3&&!FragmentOfSeren.isAttackable,"Actual world Seren does not start crystal phase");for(NPC h:new ArrayList<>(FragmentOfSeren.activePillars)){h.appendDamage(p,h.getHealth().getCurrentHealth(),Hitmark.HIT);process(h,35);}tick(20);ok(FragmentOfSeren.isAttackable,"Seren remains immune after pillars");n.appendDamage(p,n.getHealth().getCurrentHealth(),Hitmark.HIT);process(n,45);ok(p.getItems().getInventoryCount(6792)>=2&&FragmentOfSeren.specialAmount==0,"Seren reward/reset");clear(p);System.out.println("SEREN_REAL_WORLD_ID_CRYSTAL_PHASE_DAMAGE_GATE_PILLAR_DEATH_KEY_AND_RESET_PASS");}
 public static void main(String[]args)throws Exception{Thread.setDefaultUncaughtExceptionHandler((t,e)->{e.printStackTrace();System.exit(1);});Thread.currentThread().setName("GameThread");System.setProperty("solo.mode","true");Server.startServerless();scorpia();vetion();kratos();hunllef();seren();System.out.println("BOSSES_EXTRA69_PASS");System.exit(0);}
}